import{_ as a,C as n,o,c as s,E as r,a2 as i}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse(`{"title":"You Cancelled the Agent. Did Its Child Processes Actually Stop? Stop-Evidence Boundaries Through the Lens of Anywhere Agents","description":"","frontmatter":{"title":"You Cancelled the Agent. Did Its Child Processes Actually Stop? Stop-Evidence Boundaries Through the Lens of Anywhere Agents","date":"2026-08-27","column":"digital-employee","category":"daily","article_type":"engineering-analysis","edition":"research-center","research_question":"Can a cancellation request, successful termination command, disappearing known PIDs, execution-tree containment, and redispatch eligibility be represented by one stopped state?","summary":"Starting from Anywhere Agents' handling of stranded results and orphan processes, and adding a publicly rerunnable two-level Windows probe, this study separates the act of cancellation from evidence that an agent execution tree has actually stopped.","sources":"/en/research/evidence/2026-08-27-runtime-semantics-evidence-pack","project_relevance":"first-party-research","item_id":"RSEM-20260827-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-agent-stop-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-27-agent-stop-evidence.md","filePath":"en/digital-employee/2026-08-27-agent-stop-evidence.md","lastUpdated":1787845907000}`),d={name:"en/digital-employee/2026-08-27-agent-stop-evidence.md"};function l(c,e,p,h,u,g){const t=n("ArticleCover");return o(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-08-27-agent-stop-evidence-cover.png",kicker:"Digital Employee · Engineering Research",title:"You Cancelled the Agent. Did Its Child Processes Actually Stop? Stop-Evidence Boundaries Through the Lens of Anywhere Agents",summary:"Cancellation is a control action; stopping is a set of postconditions that require evidence. A zero exit code, a missing PID, containment, and redispatch eligibility cannot stand in for one another.",version:"RSEM-20260827-01",status:"Engineering Research · 2026-08-27",languageHref:"/zh/digital-employee/2026-08-27-agent-stop-evidence",languageLabel:"中文"}),e[0]||(e[0]=i(`<h1 id="you-cancelled-the-agent-did-its-child-processes-actually-stop-stop-evidence-boundaries-through-the-lens-of-anywhere-agents" tabindex="-1">You Cancelled the Agent. Did Its Child Processes Actually Stop? Stop-Evidence Boundaries Through the Lens of Anywhere Agents <a class="header-anchor" href="#you-cancelled-the-agent-did-its-child-processes-actually-stop-stop-evidence-boundaries-through-the-lens-of-anywhere-agents" aria-label="Permalink to &quot;You Cancelled the Agent. Did Its Child Processes Actually Stop? Stop-Evidence Boundaries Through the Lens of Anywhere Agents&quot;">​</a></h1><p><strong>Cancellation is an action. Stopping is a set of postconditions.</strong></p><p>Agent systems often compress the two into one reassuring badge. A user clicks Cancel, the runtime invokes a termination command, the command returns success, and the interface says Stopped. But an old child may still be writing the workspace. A grandchild may already have escaped the original process group. A result file may be temporarily unreadable rather than gone.</p><p>The important question is therefore not whether the Cancel button fired. It is: <strong>how far did the evidence actually reach?</strong></p><h2 id="_1-anywhere-agents-starts-with-a-strict-observation-rule-not-observable-is-not-the-same-as-absent" tabindex="-1">1. Anywhere Agents starts with a strict observation rule: not observable is not the same as absent <a class="header-anchor" href="#_1-anywhere-agents-starts-with-a-strict-observation-rule-not-observable-is-not-the-same-as-absent" aria-label="Permalink to &quot;1. Anywhere Agents starts with a strict observation rule: not observable is not the same as absent&quot;">​</a></h2><p>In Anywhere Agents commit <code>570c89f</code>, Yue Zhao added tooling for <code>prun-task-*</code> units left behind after interrupted fan-out work. The author reports a motivating corpus in which <strong>27 units had recorded result paths whose result files were gone, while 24.3 MiB of tail output remained</strong>. Those figures are source-reported engineering observations; we did not independently reproduce the corpus.</p><p>The more interesting part is the data model. <code>report-state</code> does not collapse a unit into a verdict such as recoverable or failed. It keeps two orthogonal fields:</p><ul><li><code>result_path_state</code>: whether the recorded result path could be resolved;</li><li><code>result</code>: whether the target is <code>present / empty / missing / unknown</code>.</li></ul><p>Only an actual <code>FileNotFoundError</code> is allowed to produce <code>missing</code>. Permission denial, I/O failure, a non-regular file, an oversized entry, or an unreadable root remains an observation error rather than being rewritten as absence.</p><p>The commit states the principle directly:</p><blockquote><p><strong>failed observation never becomes an outcome</strong></p></blockquote><p>That discipline transfers cleanly to process stopping. If a root PID is no longer observable, that establishes something about the root PID. It does not automatically establish that every descendant is gone.</p><h2 id="_2-issue-29-is-stronger-four-increasingly-strict-reaping-claims-were-each-defeated-by-a-narrower-counterexample" tabindex="-1">2. Issue #29 is stronger: four increasingly strict reaping claims were each defeated by a narrower counterexample <a class="header-anchor" href="#_2-issue-29-is-stronger-four-increasingly-strict-reaping-claims-were-each-defeated-by-a-narrower-counterexample" aria-label="Permalink to &quot;2. Issue #29 is stronger: four increasingly strict reaping claims were each defeated by a narrower counterexample&quot;">​</a></h2><p>Anywhere Agents&#39; open Issue #29 is valuable because it records a sequence of failed proof attempts rather than only a final design preference.</p><table tabindex="0"><thead><tr><th>Round</th><th>What <code>REAPED</code> was trying to establish</th><th>Counterexample</th></tr></thead><tbody><tr><td>1</td><td>a signal was sent</td><td>every <code>kill</code> failed and the unit still reported <code>REAPED</code></td></tr><tr><td>2</td><td>the recorded root was gone</td><td>a descendant ignored <code>TERM</code> and survived</td></tr><tr><td>3</td><td>the process group was empty</td><td>a descendant left the group with <code>setsid</code></td></tr><tr><td>4</td><td>repeated retained-identity snapshots converged</td><td>a transient intermediate created a grandchild between snapshots, exited, and the grandchild was never enumerated</td></tr></tbody></table><p>The fourth case is the key one. It needs no PID reuse, no query failure, no scan bound exhaustion, and no interrupted reaper. Timing alone is enough for a reaper to announce convergence while a grandchild remains alive.</p><p>That shifts the proof obligation to <strong>dispatch time</strong>. If the worker was not placed inside a kernel-backed closed set when it started, a later reaper can only infer membership from PID, parent links, and process groups—relations that can escape.</p><p>The issue therefore proposes Windows Job Objects and guaranteed POSIX session containment. It even reserves <code>REAPED</code> for kernel-backed containment and keeps that stronger result unreachable until the prerequisite exists.</p><p>This is an Anywhere Agents design discussion, not evidence that CodeFlowMu has the same defect. The transferable principle is narrower:</p><blockquote><p><strong>The broader the stop claim, the less it can rely on “I cannot see the process anymore.”</strong></p></blockquote><h2 id="_3-one-stopped-badge-can-hide-at-least-six-different-facts" tabindex="-1">3. One Stopped badge can hide at least six different facts <a class="header-anchor" href="#_3-one-stopped-badge-can-hide-at-least-six-different-facts" aria-label="Permalink to &quot;3. One Stopped badge can hide at least six different facts&quot;">​</a></h2><p>A cancellation scene is easier to reason about if the claims are separated explicitly:</p><table tabindex="0"><thead><tr><th>Evidence layer</th><th>What it establishes</th><th>What it does not establish</th></tr></thead><tbody><tr><td>cancellation requested</td><td>the runtime issued a stop intent</td><td>the OS terminated any process</td></tr><tr><td>termination command succeeded</td><td>the termination tool returned success</td><td>every descendant exited</td></tr><tr><td>root exit observed</td><td>the known wrapper/root PID is no longer observable</td><td>children, grandchildren, handles, and ports are gone</td></tr><tr><td>known child exit observed</td><td>one known direct child exited</td><td>no escaped descendant remains</td></tr><tr><td>containment proven</td><td>the execution belongs to a closed set the kernel can constrain as a unit</td><td>the workspace has no asynchronous tail writes</td></tr><tr><td>redispatch eligible</td><td>scheduling/governance allows another attempt</td><td>the previous OS execution tree has been fully proven absent</td></tr></tbody></table><p>These layers may refer to one another. They should not sign for one another.</p><p>Two especially dangerous jumps are:</p><p><strong><code>taskkill exit 0 → entire tree gone</code></strong></p><p>and:</p><p><strong><code>retry allowed → old execution definitely gone</code></strong></p><p>The first promotes a tool result into an operating-system containment claim. The second promotes governance authority into a process fact.</p><h2 id="_4-what-our-windows-probe-actually-establishes" tabindex="-1">4. What our Windows probe actually establishes <a class="header-anchor" href="#_4-what-our-windows-probe-actually-establishes" aria-label="Permalink to &quot;4. What our Windows probe actually establishes&quot;">​</a></h2><p>CodeFlowMu is the local multi-agent runtime we are developing. Its first-party Windows managed-command path invokes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>taskkill /PID &lt;pid&gt; /T /F</span></span></code></pre></div><p>for cancellation.</p><p>We deliberately did not translate that command into a tree-containment guarantee. Instead, we ran a narrow probe: create a fresh temporary directory, start a wrapper, let the wrapper start one long-lived direct child, confirm both PIDs are observable, run the same <code>taskkill /T /F</code> operation against the wrapper, and then observe the two PIDs separately.</p><p>The recorded controlled-host result was:</p><ul><li>termination exit code = <code>0</code>;</li><li>wrapper exit observed = <code>true</code>;</li><li>direct-child exit observed = <code>true</code>;</li><li><code>kernel_containment_proven = false</code>.</li></ul><p>So the PASS supports only this statement:</p><blockquote><p><strong>On this Windows host, for this wrapper-plus-direct-child sample, <code>/T</code> did not kill only the wrapper; both known PIDs were observed to exit.</strong></p></blockquote><p>It does not support:</p><blockquote><p>arbitrary-depth Windows agent process trees have been proven contained and reaped.</p></blockquote><p>The public evidence pack now includes a Windows-specific probe implementing that disclosed two-level contract, the deidentified recorded result, and a record-check. Readers can rerun the same experiment on their own Windows machine. On non-Windows platforms the probe refuses to run rather than manufacturing a PASS.</p><p>That is a stronger evidence posture than publishing only “1/1 PASS,” while still preserving the same narrow conclusion. Another PASS on another Windows host would still not cover escaped descendants, transient intermediates, privilege boundaries, deeper trees, containers, or remote workers.</p><h2 id="_5-cancelled-is-best-treated-as-a-control-plane-outcome-not-a-containment-certificate" tabindex="-1">5. <code>cancelled</code> is best treated as a control-plane outcome, not a containment certificate <a class="header-anchor" href="#_5-cancelled-is-best-treated-as-a-control-plane-outcome-not-a-containment-certificate" aria-label="Permalink to &quot;5. \`cancelled\` is best treated as a control-plane outcome, not a containment certificate&quot;">​</a></h2><p>There is also a semantic issue on our side worth keeping visible.</p><p>The current first-party managed-command path can transition a command record to <code>cancelled</code> after the termination tool succeeds. That state is useful to the control plane: it means <strong>the cancellation operation completed under the current mechanism</strong>. But if a UI or scheduler reads <code>cancelled</code> as “every descendant has been proven absent,” the interpretation has outrun the evidence.</p><p>A stronger stop record would separate the evidence axes, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cancel_request          sent</span></span>
<span class="line"><span>termination_command     exit_0</span></span>
<span class="line"><span>root_exit               observed</span></span>
<span class="line"><span>known_child_exit        observed</span></span>
<span class="line"><span>containment             unverified</span></span>
<span class="line"><span>workspace_quiescence    unverified</span></span>
<span class="line"><span>redispatch_eligibility  decided_by_existing_rule</span></span></code></pre></div><p>Unknown is not failure. It is also not permission to paint the entire execution green.</p><h2 id="_6-silence-must-not-be-rewritten-as-death-either" tabindex="-1">6. Silence must not be rewritten as death either <a class="header-anchor" href="#_6-silence-must-not-be-rewritten-as-death-either" aria-label="Permalink to &quot;6. Silence must not be rewritten as death either&quot;">​</a></h2><p>Stop semantics fail in the opposite direction too. A runtime should not infer death simply because no new output appeared.</p><p>We reran an existing managed-command fixture in which a job experiences a simulated two hours of silence, 101 observations, and restart recovery after index loss. The targeted test remained <strong>1/1 PASS</strong>.</p><p>That fixture does not prove containment. It protects another boundary:</p><blockquote><p><strong>silence ≠ death</strong></p></blockquote><p>Together with:</p><blockquote><p><strong>cancel requested ≠ tree gone</strong></p></blockquote><p>it expresses the same discipline: record what the runtime actually observed rather than filling missing evidence with a convenient terminal state.</p><h2 id="_7-the-dangerous-gap-is-between-cancellation-and-redispatch" tabindex="-1">7. The dangerous gap is between cancellation and redispatch <a class="header-anchor" href="#_7-the-dangerous-gap-is-between-cancellation-and-redispatch" aria-label="Permalink to &quot;7. The dangerous gap is between cancellation and redispatch&quot;">​</a></h2><p>Why does this distinction matter operationally? Because the expensive failure is often not the first failed run. It is the second run starting too early.</p><p>The wrapper is gone, but an escaped descendant still writes files. A PM or scheduler approves a retry. A new agent receives the same workspace. Local lease rules may prevent two formal attempts on the same controlled dispatch path from holding the active lease simultaneously, but a lease cannot kill an OS process that has escaped the runtime&#39;s observation surface.</p><p>Redispatch therefore needs two different questions:</p><ul><li><strong>governance / scheduling eligibility</strong>: may a new attempt be created?</li><li><strong>execution-environment safety evidence</strong>: how far has the previous execution scene actually been proven quiescent or contained?</li></ul><p>A valid scheduling decision cannot sign an operating-system postcondition.</p><h2 id="_8-the-next-counterexamples-are-more-valuable-than-a-brighter-stopped-badge" tabindex="-1">8. The next counterexamples are more valuable than a brighter Stopped badge <a class="header-anchor" href="#_8-the-next-counterexamples-are-more-valuable-than-a-brighter-stopped-badge" aria-label="Permalink to &quot;8. The next counterexamples are more valuable than a brighter Stopped badge&quot;">​</a></h2><p>The useful next work is adversarial evidence, not a stronger color:</p><ul><li>wrapper exits while a direct child survives;</li><li>child escapes its original process group or parent relation;</li><li>a transient intermediate creates a grandchild between observations;</li><li>an old result file continues growing after root exit;</li><li>cancellation completion races with redispatch;</li><li>processes exit while ports, file locks, or helper resources remain.</li></ul><p>Each experiment should leave the same structure:</p><p><strong>action taken → objects observed → postconditions proven → postconditions still unknown → actions now permitted.</strong></p><p>That is a better long-running-runtime contract than compressing the scene into <code>cancelled=true</code>.</p><h2 id="conclusion-stopping-is-not-a-button-result-it-is-a-scoped-proof" tabindex="-1">Conclusion: stopping is not a button result; it is a scoped proof <a class="header-anchor" href="#conclusion-stopping-is-not-a-button-result-it-is-a-scoped-proof" aria-label="Permalink to &quot;Conclusion: stopping is not a button result; it is a scoped proof&quot;">​</a></h2><p>Anywhere Agents&#39; <code>report-state</code> work reminds us that <strong>a failed observation must not become an outcome</strong>. Issue #29 goes further: <strong>if the execution tree was never made a kernel-bounded closed set at spawn time, later enumeration has severe limits as proof that the tree is gone.</strong></p><p>Our two-level Windows probe contributes a smaller fact: <code>taskkill /T /F</code> was observed to remove both the wrapper and one direct child in one controlled sample. That fact is useful precisely because it stops there.</p><blockquote><p><strong>Cancellation is an action. Stopping is a set of postconditions. Execution-tree containment is a stronger proof still.</strong></p></blockquote><p>A reliable agent runtime does not need to pretend it knows everything. Before redispatch, it should tell the next executor exactly <strong>what was observed to stop, what merely disappeared from view, and what remains unproven.</strong></p><hr><h2 id="public-evidence" tabindex="-1">Public evidence <a class="header-anchor" href="#public-evidence" aria-label="Permalink to &quot;Public evidence&quot;">​</a></h2><ul><li><a href="/joinwell52/en/research/evidence/2026-08-27-runtime-semantics-evidence-pack"><strong>Runtime Semantics: Public Evidence Pack for Three Articles</strong></a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-tree-probe.mjs"><strong>R1 public Windows <code>taskkill /T /F</code> probe</strong></a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result.json"><strong>R1 deidentified recorded result</strong></a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result-check.mjs"><strong>R1 recorded-result check</strong></a></li></ul><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><h3 id="anywhere-agents" tabindex="-1">Anywhere Agents <a class="header-anchor" href="#anywhere-agents" aria-label="Permalink to &quot;Anywhere Agents&quot;">​</a></h3><ul><li><a href="https://github.com/yzhao062/anywhere-agents/commit/570c89f4c4bfa03bc5cea0a43a7fcf9fef0261ab" target="_blank" rel="noreferrer"><strong>commit <code>570c89f</code></strong></a>: used for the separation between result-path observation and result outcome, and for the author-reported corpus of 27 stranded units and 24.3 MiB of tail. Those figures are source-reported and were not independently reproduced here.</li><li><a href="https://github.com/yzhao062/anywhere-agents/issues/29" target="_blank" rel="noreferrer"><strong>Issue #29</strong></a>: used for the four progressively stronger orphan-reaping claims defeated by live counterexamples, and for the design argument that tree-wide proof belongs in dispatch-time kernel-backed containment. The issue remains open and is not presented as a completed shipped solution.</li></ul><p>Anywhere Agents is used as a public research and engineering reference. It does not establish a shared root cause, implementation lineage, or equivalent containment design in CodeFlowMu.</p><h3 id="first-party-evidence" tabindex="-1">First-party evidence <a class="header-anchor" href="#first-party-evidence" aria-label="Permalink to &quot;First-party evidence&quot;">​</a></h3><p>R1 covers one wrapper-plus-direct-child sample on one Windows host. The public probe makes the same two-level contract rerunnable, but it does not upgrade the historical PASS into Job Object or kernel-containment proof. This article does not claim equivalent guarantees for arbitrary Windows process trees, independent runtimes, network filesystems, containers, or remote workers.</p>`,82))])}const f=a(d,[["render",l]]);export{b as __pageData,f as default};
